export function buildSearchIndex() {
  const items = []
  for (const mod of modules) {
    items.push({
      id: mod.slug,
      type: 'module',
      title: mod.title,
      subtitle: mod.subtitle,
      body: mod.description,
      module: mod.number,
      slug: mod.slug,
      url: `/modules/${mod.slug}/`,
    })
    for (const slide of mod.slides) {
      const text = [slide.tag, slide.heading, slide.body].filter(Boolean).join(' ')
      items.push({
        id: slide.id,
        type: 'slide',
        title: slide.heading || '',
        tag: slide.tag || '',
        body: text,
        module: mod.number,
        slug: mod.slug,
        url: `/modules/${mod.slug}/`,
      })
    }
  }
  return items
}

